from lib import *
S = SS('f175')
R = J('f175'); en = R['env']; pf = R['prefix']; k = list(en); kp = list(pf)
steps = [
    step("同一个请求(客户端写了全套 X-Forwarded-* 头:For: 203.0.113.5, 10.0.0.1;Proto: https;Host: shop.example.test;Port: 8443;Prefix: /app,请求直接发给 internal:8000),不同的 ProxyFix 参数下 Flask 看到的:没有 ProxyFix → remote_addr 127.0.0.1、scheme http、host internal:8000、外部链接 http://internal:8000/items/(这些头全被忽略)。x_for=1 加 x_proto=1 → remote_addr 变成 10.0.0.1(链里最右边那个)、scheme 变成 https,host 还是 internal:8000。再加 x_host=1 → host 变成 shop.example.test,外部链接是 https://shop.example.test/items/。x_for=2 → remote_addr 变成 203.0.113.5(从右往左数第 2 个)。每个参数是「信任几层代理」,只改对应的那一项。", t=tl(S(1)), done=lidx(S(1), '[没有 ProxyFix]', '[x_for=1, x_proto=1]', '[x_for=1, x_proto=1, x_host=1]'), mark=lidx(S(1), '[x_for=2]'), kv=KV([['x_for / x_proto / x_host / x_port / x_prefix', '各自改一项,数字 = 信任的层数'], ['没有 ProxyFix', '所有 X-Forwarded-* 都被忽略']], ['x_for / x_proto / x_host / x_port / x_prefix'])),
    step("全部设成 1(x_for/proto/host/port/prefix):remote_addr = 10.0.0.1、scheme = https、host = shop.example.test:8443、request.script_root = /app;url_for('items') 变成 /app/items/,静态文件 /app/static/a.css,外部链接 https://shop.example.test:8443/app/items/。x_prefix 改的是 SCRIPT_NAME,所以 Flask 生成的所有 URL 都带上前缀。", t=tl(S(1)), done=lidx(S(1), '全部 =1'), kv=KV([['x_prefix', '改 SCRIPT_NAME,url_for 与 static 都带前缀']], ['x_prefix'])),
    step("真实的 nginx 把应用挂在子路径(location /app/ { proxy_pass http://后端/; },nginx 去掉 /app 前缀再转发):没有 ProxyFix 时,浏览器访问 /app/items/,url_for 生成 /items/、静态文件 /static/a.css、表单 action /items/、重定向 Location /items/——所有链接都丢了 /app,点进去 404。只在 Flask 里加 ProxyFix(x_prefix=1) 但 nginx 没传 X-Forwarded-Prefix,结果完全一样(没有头就没有前缀)。", t=tl(S(2)), mark=lidx(S(2), '[没有 ProxyFix]', '但 nginx 没传'), kv=KV([['ProxyFix 不够', 'nginx 也要传 X-Forwarded-Prefix'], ['缺了前缀', '链接和重定向都丢 /app']], ['缺了前缀'])),
    step("nginx 加上 proxy_set_header X-Forwarded-Prefix /app;、Flask 用 ProxyFix(x_prefix=1)(同时 x_for、x_proto、x_host):url_for 是 /app/items/,静态 /app/static/a.css,表单 action /app/items/,重定向 Location /app/items/——全部正确。子路径部署要两边配合:代理传头、应用的 ProxyFix 信任它(也可以用 APPLICATION_ROOT,本篇没有验证)。", t=tl(S(2)), done=lidx(S(2), 'X-Forwarded-Prefix: /app]', '/app/items/'), kv=KV([['代理传头', 'X-Forwarded-Prefix: /app'], ['应用信任', 'ProxyFix(x_prefix=1)']], ['代理传头'])),
]
A = mkartf('f175', 175, 'Flask,ProxyFix,X-Forwarded,子路径部署,nginx,真实验证,动画演示',
    '实测 ProxyFix 的作用:每个参数各改 WSGI 环境里的哪一项(remote_addr、scheme、host、script_root)、x_for 的数字是从右往左信任几层、x_prefix 让 url_for 与静态文件与重定向带上前缀;用真实的 nginx 把应用挂在 /app/ 子路径时,必须代理传 X-Forwarded-Prefix 且应用的 ProxyFix 信任它。',
    'ProxyFix 的每个参数到底改了什么?子路径部署为什么链接全丢了前缀?只配 ProxyFix 够不够?这篇用同一个请求对比各参数,再用真实的 nginx 子路径验证(HTTPS 与 X-Forwarded-For 见第 134、135 篇)。',
    [('10.0.0.1 → 203.0.113.5', 'x_for 从 1 改成 2 时 remote_addr 的变化(链 203.0.113.5, 10.0.0.1)'), ('/app/items/', '同时配好 nginx 与 ProxyFix 后 url_for 生成的地址'), ('X-Forwarded-Prefix', '子路径部署时 nginx 必须传的头,缺它 ProxyFix 的 x_prefix 无效')],
    [('各参数改了什么(含 x_prefix)', '<p>上一篇:<a href="flask-nginx-reverse-proxy.html">Nginx 反向代理</a>;下一篇:<a href="flask-static-production.html">静态文件生产部署</a>。</p>'), ('nginx 子路径部署', '<p>nginx 是自己起的实例(非默认端口),gunicorn 用 --forwarded-allow-ips 设成不信任回环,让 ProxyFix 来负责。</p>')],
    steps, [ENV_F + '。Werkzeug 3.1.9 ProxyFix、nginx 1.31.6', '没有验证:APPLICATION_ROOT 配置与 ProxyFix 的 x_prefix 的差别、蓝图 url_prefix 与代理前缀叠加、x_port 在非标准端口下的细节、Forwarded 标准头(RFC 7239)'], 'ProxyFix 的作用')
